import {approvedAtlasStatuses,retryFailedApprovedAtlases,subscribeApprovedAtlases} from '../approved-atlas-runtime.mjs';
import {loadApprovedPlayers,approvedPlayerDrawStatus} from '../art/approved-player-field.mjs';
import {repaintApprovedIntroAfterRetry,invalidateApprovedIntroRepaints} from '../art/approved-intro.mjs';
export function installAtlasRetryStatus(doc=document,win=window){
 const box=doc.createElement('div'),label=doc.createElement('span'),button=doc.createElement('button');box.id='qa-atlas-status';box.setAttribute('role','status');box.style.cssText='box-sizing:border-box;flex:none;padding:4px 8px;background:#fff3bf;color:#16384a;font:12px/1.5 system-ui;max-height:100px;overflow:auto;position:relative;z-index:3';button.type='button';button.textContent='인물 이미지 다시 불러오기';button.style.cssText='min-height:44px;margin-left:8px';box.append(label,button);let disposed=false,busy=false,timer=null,generation=0;
 const guard=e=>e.stopPropagation();box.addEventListener('keydown',guard); // keyup must reach field release handlers.
 const mount=()=>{if(disposed)return;const host=[...doc.querySelectorAll('dialog[open]')].at(-1)??doc.getElementById('canonical-world')??doc.body;if(box.parentElement!==host)host.prepend(box)};
 const update=()=>{if(disposed)return;const states=approvedAtlasStatuses(),failed=states.filter(s=>['failed','paused'].includes(s.status));label.textContent=failed.length?'인물 이미지를 불러오지 못했거나 대기 중입니다. 연결을 확인하고 다시 시도해 주세요.':'개발 QA · 인물 이미지 로딩 상태 '+states.filter(s=>s.status==='ready').length+'/'+states.length;box.dataset.atlasRequests=JSON.stringify(states);box.dataset.playerDraw=JSON.stringify(approvedPlayerDrawStatus());button.hidden=!failed.length;button.disabled=busy;mount()};
 const isActive=token=>!disposed&&token===generation&&doc.visibilityState!=='hidden';
 button.onclick=async()=>{if(busy||disposed||doc.visibilityState==='hidden')return;const token=++generation;busy=true;update();try{await retryFailedApprovedAtlases();if(!isActive(token))return;await loadApprovedPlayers();if(!isActive(token))return;await repaintApprovedIntroAfterRetry({isActive:()=>isActive(token)})}finally{if(token===generation){busy=false;update()}}};
 const unsubscribe=subscribeApprovedAtlases(update),observer=new win.MutationObserver(mount);observer.observe(doc.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
 const stop=()=>{if(timer!==null)win.clearInterval(timer);timer=null};const start=()=>{if(!disposed&&timer===null){update();timer=win.setInterval(update,500)}};
 const hide=()=>{generation++;busy=false;invalidateApprovedIntroRepaints();stop()},show=()=>{start();const token=generation;void repaintApprovedIntroAfterRetry({isActive:()=>isActive(token)})};const visibility=()=>doc.visibilityState==='hidden'?hide():show();doc.addEventListener('visibilitychange',visibility);win.addEventListener('pagehide',hide);win.addEventListener('pageshow',show);if(doc.visibilityState!=='hidden')start();
 return{box,dispose(){if(disposed)return;disposed=true;generation++;invalidateApprovedIntroRepaints();stop();unsubscribe();observer.disconnect();box.removeEventListener('keydown',guard);win.removeEventListener('pagehide',hide);win.removeEventListener('pageshow',show);doc.removeEventListener('visibilitychange',visibility);box.remove()}};
}
